package com.yeyamo_mobile.api.recommendation_service.application.scoring;
import java.util.Locale;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.recommendation_service.domain.*;
@Component public class PreferenceScoringStrategy implements ScoringStrategy{public String name(){return"preferences";}public double score(Candidate c,RecommendationProfile p,RecommendationContext x){double region=java.util.Objects.equals(c.regionCode(),p.preferredRegion())&&c.regionCode()!=null?15:0;double learned=Math.min(20,Math.max(0,p.categoryAffinity().getOrDefault(c.categoryCode(),0d))*2);double explicit=c.categoryCode()!=null&&p.interestCodes().contains(c.categoryCode().toLowerCase(Locale.ROOT))?25:0;return region+learned+explicit;}}
